INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('c0306a83-b3e3-481a-8c69-e6e8beab0b8f', 'industry', 'medium', 'Effervescent Vitamin C 1000mg', NULL, NULL, ARRAY[]::text[], NULL, '{"release":true}'::jsonb, 'Moisture is the #1 enemy — RH<30%, ethanol granulation, desiccant packaging.', 'Any visible moisture or premature fizzing in-process means immediate batch hold.', '2026-06-13T08:52:14.915559+00:00', '{"qc":[{"test":"Effervescence time","result":"<60 seconds","shouldPass":true},{"test":"pH of solution","result":"4.5","shouldPass":true},{"test":"Weight","result":"2.45g ±1%","shouldPass":true}],"env":{"tempRange":[18,22],"humidityRange":[10,25]},"process":{"drying":{"max":50,"min":40,"unit":"°C","target":45},"mixing":{"prompt":"Mixing","correct":1,"options":["5 min @ 15 rpm","15 min @ 20 rpm","60 min @ 80 rpm"]},"coating":{"prompt":"Coating","correct":0,"options":["None","Sugar","Enteric"]},"packaging":{"prompt":"Packaging","correct":0,"options":["Alu-Alu strip with desiccant","Open blister","PVC bottle"]},"compression":{"prompt":"Hardness","correct":1,"options":["4-6 kp","8-12 kp","20+ kp"]},"granulation":{"prompt":"Granulation","correct":2,"options":["Wet granulation (water)","Dry granulation","Fluid bed with ethanol"]}},"product":"Effervescent Vitamin C 1000mg","release":true,"batchSize":"30,000 tablets","distractors":["Magnesium Stearate","Lactose","Talc"],"ingredients":[{"max":1010,"min":990,"name":"Ascorbic Acid","role":"Active","unit":"g","target":1000},{"max":810,"min":790,"name":"Sodium Bicarbonate","role":"Effervescent base","unit":"g","target":800},{"max":606,"min":594,"name":"Citric Acid Anhydrous","role":"Effervescent acid","unit":"g","target":600},{"max":52,"min":48,"name":"PEG 6000","role":"Lubricant","unit":"g","target":50}]}'::jsonb, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('faa03daa-afa2-422b-8d4f-239df7e11ec8', 'industry', 'hard', 'Modified-release Metformin 500mg', NULL, NULL, ARRAY[]::text[], NULL, '{"release":true}'::jsonb, 'HPMC matrix controls release; do not include disintegrants — they break SR profile.', 'Adding a fast disintegrant to an SR matrix is a classic formulation error — destroys controlled release.', '2026-06-13T08:52:14.915559+00:00', '{"qc":[{"test":"Dissolution 1h","result":"30%","shouldPass":true},{"test":"Dissolution 6h","result":"75%","shouldPass":true},{"test":"Dissolution 12h","result":"95%","shouldPass":true}],"env":{"tempRange":[18,25],"humidityRange":[30,50]},"process":{"drying":{"max":60,"min":50,"unit":"°C","target":55},"mixing":{"prompt":"Mixing","correct":1,"options":["5 min @ 15 rpm","20 min @ 25 rpm","60 min @ 80 rpm"]},"coating":{"prompt":"Coating","correct":1,"options":["None","Film (HPMC barrier)","Enteric"]},"packaging":{"prompt":"Packaging","correct":2,"options":["PVC blister","Alu-Alu blister","HDPE bottle with desiccant"]},"compression":{"prompt":"Hardness","correct":1,"options":["4-6 kp","10-14 kp","20+ kp"]},"granulation":{"prompt":"Granulation","correct":1,"options":["Direct compression","Wet granulation (purified water)","High-shear with isopropanol"]}},"product":"Metformin SR 500mg","release":true,"batchSize":"40,000 tablets","distractors":["Croscarmellose Sodium","Sodium Starch Glycolate","PVP K30"],"ingredients":[{"max":505,"min":495,"name":"Metformin HCl","role":"Active","unit":"g","target":500},{"max":153,"min":147,"name":"HPMC K100M","role":"SR matrix","unit":"g","target":150},{"max":82,"min":78,"name":"Microcrystalline Cellulose","role":"Filler","unit":"g","target":80},{"max":5.2,"min":4.8,"name":"Magnesium Stearate","role":"Lubricant","unit":"g","target":5}]}'::jsonb, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('bfc4e7df-fa15-45b4-b7b5-cecdc1085b38', 'warehousing', 'hard', 'Controlled substance receipt + FEFO mix', NULL, NULL, ARRAY[]::text[], NULL, '{"completed":true}'::jsonb, 'Controlled drugs in secure zone with register entry; FEFO on both opioids; morphine discrepancy flagged.', 'Any controlled-substance discrepancy is a regulatory event — investigate, document, and escalate immediately.', '2026-06-13T08:53:08.880861+00:00', NULL, '{"zones":["Ambient","Cool Room 2-8°C","Freezer","Light-Protected","Controlled Substances"],"dispatch":[{"drug":"Morphine 10mg/mL","batches":[{"batch":"MOR-700","expiry":"2026-10-31"},{"batch":"MOR-808","expiry":"2027-07-31"}],"correctBatch":"MOR-700"},{"drug":"Midazolam","batches":[{"batch":"MDZ-100","expiry":"2026-09-30"},{"batch":"MDZ-220","expiry":"2027-04-30"}],"correctBatch":"MDZ-100"}],"expiring":[{"drug":"Nitroglycerin SL","batch":"NTG-117","expiry":"in 40 days","hasOrder":false,"correctAction":"Mark for Return to Supplier"}],"shipments":[{"id":"S1","drug":"Morphine 10mg/mL","batch":"MOR-808","expiry":"2027-07-31","controlled":true,"correctZone":"Controlled Substances","requirement":"Controlled substance — register entry"},{"id":"S2","drug":"Midazolam","batch":"MDZ-220","expiry":"2027-04-30","controlled":true,"correctZone":"Controlled Substances","requirement":"Schedule IV — secure storage"},{"id":"S3","drug":"Nitroglycerin SL","batch":"NTG-117","expiry":"2026-12-31","correctZone":"Light-Protected","requirement":"Protect from light"},{"id":"S4","drug":"Paracetamol IV","batch":"PCMIV-202","expiry":"2027-09-30","correctZone":"Ambient","requirement":"Store below 25°C"}],"reconciliation":[{"item":"Morphine 10mg/mL","actual":92,"expected":100,"investigate":true},{"item":"Paracetamol IV","actual":300,"expected":300,"investigate":false}]}'::jsonb, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('43cb5018-8edc-4163-9ee5-e73c7a62b20c', 'industry', 'hard', 'Omeprazole 20mg Enteric Capsule', NULL, NULL, ARRAY[]::text[], NULL, '{"release":true}'::jsonb, 'Acid-labile API needs HPMC subcoat between API and enteric coat to prevent degradation.', 'Omeprazole degrades on contact with even trace acid — multi-layer pellet system is mandatory.', '2026-06-13T08:53:08.880861+00:00', '{"qc":[{"test":"Acid resistance 2h","result":"<10% release","shouldPass":true},{"test":"Buffer dissolution 45min","result":"Q=80%","shouldPass":true},{"test":"Assay","result":"98.5%","shouldPass":true}],"env":{"tempRange":[18,22],"humidityRange":[15,30]},"process":{"drying":{"max":45,"min":35,"unit":"°C","target":40},"mixing":{"prompt":"Subcoat application","correct":1,"options":["Apply enteric directly","Apply HPMC subcoat first","No subcoat"]},"coating":{"prompt":"Outer coat","correct":1,"options":["Sugar","Methacrylic enteric","None"]},"packaging":{"prompt":"Packaging","correct":1,"options":["PVC blister","Alu-Alu with desiccant","Open jar"]},"compression":{"prompt":"Capsule fill","correct":1,"options":["Compress into tablets","Fill into HPMC capsules","Direct dispensing"]},"granulation":{"prompt":"Pellet build","correct":1,"options":["Wet granulation","Layering on sugar spheres","Direct compression"]}},"product":"Omeprazole 20mg DR Capsule","release":true,"batchSize":"60,000 capsules","distractors":["Sodium Bicarbonate","Croscarmellose","Talc"],"ingredients":[{"max":20.2,"min":19.8,"name":"Omeprazole","role":"Active","unit":"g","target":20},{"max":305,"min":295,"name":"Sugar Spheres (cores)","role":"Substrate","unit":"g","target":300},{"max":41,"min":39,"name":"HPMC (subcoat)","role":"Subcoat polymer","unit":"g","target":40},{"max":82,"min":78,"name":"Methacrylic Acid Copolymer","role":"Enteric coat","unit":"g","target":80}]}'::jsonb, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
